def spreadsheet_cells_in_range(s):
    start,end=s.split(':');answer=[]
    for column in range(ord(start[0]),ord(end[0])+1):
        for row in range(int(start[1]),int(end[1])+1):answer.append(f'{chr(column)}{row}')
    return answer

